SELECT arwr.*
FROM t_allocation_ret_warehouse_record arwr
WHERE arwr.record_id = #{recordId}
  AND arwr.deleted_flag = #{deletedFlag}

SELECT * FROM t_allocation_ret_warehouse_record

    record_id IN

        #{id}


        AND marked_flag = #{markedFlag}



ORDER BY t_allocation_ret_warehouse_record.create_time DESC

SELECT t_allocation_ret_warehouse_record.*, t_allocation_ret_warehouse.* FROM t_allocation_ret_warehouse_record LEFT JOIN t_allocation_ret_warehouse on t_allocation_ret_warehouse_record.record_id = t_allocation_ret_warehouse.record_id
t_allocation_ret_warehouse.deleted_flag = #{queryForm.deletedFlag}
AND INSTR(allocate_sprinkler_serial,#{queryForm.allocateSprinklerSerial})
AND INSTR(allocate_sprinkler_model,#{queryForm.allocateSprinklerModel})
AND INSTR(allocate_purpose,#{queryForm.allocatePurpose})
AND INSTR(allocate_color,#{queryForm.allocateColor})
AND allocate_position = #{queryForm.allocatePosition}
AND allocate_sprinkler_is_new = #{queryForm.allocateSprinklerIsNew}
AND INSTR(ret_warehouse_sprinkler_serial,#{queryForm.retWarehouseSprinklerSerial})
AND INSTR(ret_warehouse_sprinkler_model,#{queryForm.retWarehouseSprinklerModel})
AND INSTR(ret_warehouse_machine,#{queryForm.retWarehouseMachine})
AND INSTR(ret_warehouse_color,#{queryForm.retWarehouseColor})
AND ret_warehouse_position = #{queryForm.retWarehousePosition}
AND ret_warehouse_sprinkler_is_new = #{queryForm.retWarehouseSprinklerIsNew}
AND INSTR(ret_warehouse_reason,#{queryForm.retWarehouseReason})
AND INSTR(ret_warehouse_real_reason,#{queryForm.retWarehouseRealReason})
AND INSTR(note,#{queryForm.note})
AND status = #{queryForm.status}
AND t_allocation_ret_warehouse.disabled_flag = #{queryForm.disabledFlag}
ORDER BY t_allocation_ret_warehouse_record.create_time DESC
